                            "type": "string"
                        },
                        "email": {
                            "type": "string"
                        },
                        "phoneNumber": {
                            "type": "string"
                        },
                        "phoneNote": {
                            "type": "string"
                        }
                    }
                },
                "accountState": {
                    "type": "object",
                    "properties": {
                        "userType": {
                            "type": "string"
                        },
                        "status": {
                            "type": "string"
                        },
                        "verificationStatus": {
                            "type": "string"
                        }
                    }
                },
                "profileCompletionStatus": {
                    "type": "object",
                    "properties": {
                        "personalDetails": {
                            "type": "boolean"
                        },
                        "pregnancyDetails": {
                            "type": "boolean"
                        },
                        "lossDetails": {
                            "type": "boolean"
                        },
                        "healingDetails": {
                            "type": "boolean"
                        }
                    }
                },
                "metadata": {
                    "type": "object",
                    "properties": {
                        "_id": {
                            "type": "string"
                        },
                        "timezone": {
                            "type": "string"
                        },
